-- Exact original bHF conversion products. Enhanced source inheritance remains unqualified.
CREATE TABLE native_conversion_item_actions (
 item_ref integer PRIMARY KEY CHECK(item_ref>0), action_id integer NOT NULL UNIQUE CHECK(action_id>0),
 products jsonb NOT NULL CHECK(jsonb_typeof(products)='object'), main_reference integer NOT NULL,
 source_sha256 text NOT NULL CHECK(source_sha256 ~ '^[0-9a-f]{64}$')
);
